itemPrice.example:
const price = kcds.players.Inventory.itemPrice('apple');
if (price) {
  console.info(`new ${price.pristine}, as it is ${price.current}`);
}

itemPrice.exampleCs:
var price = Inventory.ItemPrice("apple");
if (price)
{
    Log.Info($"new {price["pristine"]}, as it is {price["current"]}");
}

renameItem.example:
const { Inventory } = kcds.players;

Inventory.renameItem('apple', 'Rattay apple');
Inventory.renameItem('apple', null);

overrideStats.example:
const { Inventory } = kcds.players;

Inventory.overrideStats('longSwordDuel', { attack: 210, strReq: 12 });
Inventory.overrideStats('longSwordDuel', null);

get.example:
const stock = kcds.players.Inventory.get(player);
const coins = stock?.items
  .filter((row) => row.name === 'money')
  .reduce((total, row) => total + row.amount, 0);

get.exampleCs:
var stock = Inventory.Get(player);
var coins = stock.IsNull
    ? 0
    : stock["items"].Where((row) => row["name"].AsString() == "money").Sum((row) => row["amount"].AsNumber());

add.example:
const answer = kcds.players.Inventory.add(player, { item: 'apple', amount: 3 });
if (!answer.ok) {
  console.log(`refused: ${answer.code}`);
}

add.exampleCs:
var answer = Inventory.Add(player, new { item = "apple", amount = 3 });
if (!answer["ok"])
{
    Log.Info($"refused: {answer["code"]}");
}

remove.example:
const { Inventory } = kcds.players;

const apples = Inventory.get(player).items.find((row) => row.name === 'apple');
if (apples) {
  Inventory.remove(player, { units: [{ id: apples.id, amount: 1 }] });
}

remove.exampleCs:
var apples = Inventory.Get(player)["items"].FirstOrDefault(row => row["name"].AsString() == "apple");
if (apples)
{
    Inventory.Remove(player, new { units = new object[] { new { id = apples["id"], amount = 1 } } });
}

