stopWhenUsed.example:
// client
const { Inventory } = kcds.players;

const handlerId = Inventory.whenUsed('herb_mint', () => {});
Inventory.stopWhenUsed(handlerId);

beforeCommit.example:
// Players in the stocks can take up, buy and drop nothing.
const { Inventory } = kcds.players;
const inStocks = new Set();

Inventory.beforeCommit((transaction) => {
  return !inStocks.has(transaction.player.id);
});

beforeCommit.exampleLua:
-- Players in the stocks can take up, buy and drop nothing.
local Inventory = kcds.players.Inventory
local inStocks = {}

Inventory.beforeCommit(function(transaction, verdict)
  verdict(not inStocks[transaction.player.id])
end)

beforeCommit.exampleCs:
// Players in the stocks can take up, buy and drop nothing.
var inStocks = new HashSet<double>();

Inventory.BeforeCommit((JsValue transaction, JsValue verdict) =>
{
    verdict.Invoke(!inStocks.Contains(transaction["player"]["id"].AsNumber()));
});

stopBeforeCommit.example:
const { Inventory } = kcds.players;

const handlerId = Inventory.beforeCommit(() => true);
Inventory.stopBeforeCommit(handlerId);
